package org.apache.commons.text;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringSubstitutor_ESTest_test42 extends StringSubstitutor_ESTest_scaffolding {

    /**
     * Exercises {@link StringSubstitutor#replaceIn(StringBuilder)} with the default
     * "${...}" variable syntax over a buffer that contains both an escaped variable
     * marker ("$${") and a complete variable reference ("${}").
     *
     * <p>The buffer is assembled with chained {@code append(...)} calls. Each call
     * returns the same underlying {@link StringBuilder}, so they all mutate one
     * object — the final {@code append} copies the buffer's own current contents
     * onto its end. Note that a {@code new char[5]} is filled with the NUL
     * character ('�'), so four NULs precede the '$'.</p>
     */
    @Test(timeout = 4000)
    public void replaceInRewritesEscapedAndVariableMarkers() throws Throwable {
        StringSubstitutor substitutor = new StringSubstitutor();

        // Five-character array whose last slot is '$'; the other four stay as NUL ('�').
        char[] paddedDollar = new char[5];
        paddedDollar[4] = '$';

        // All appends operate on the same builder instance.
        StringBuilder buffer = new StringBuilder("}");
        buffer.append(paddedDollar);            // -> "}����$"
        buffer.append((CharSequence) "${");     // -> "}����$${"
        buffer.append((Object) buffer);         // append the buffer's own current contents

        boolean altered = substitutor.replaceIn(buffer);

        assertTrue(altered);
        assertEquals("}����${}����$${", buffer.toString());
    }
}
